def parse_instructions(instructions):
    valid_ops = {"mov", "inc", "dec"}
    result = []

    for instr in instructions:
        parts = instr.split()
        if len(parts) != 3:
            continue

        op, reg, value = parts

        if op not in valid_ops:
            continue

        if not (len(reg) == 1 and reg.islower()):
            continue

        try:
