from typing import List

def parse_table(content: str) -> List[List[int]]:
    result: List[List[int]] = []
    for line in content.splitlines():
        line = line.strip()
        if not line or line == '|':
            continue
        if not line.startswith('|') or not line.endswith('|'):
            continue

        # Split by '|' and filter out empty parts
        parts = [p.strip() for p in line.split('|')]
        # Remove first and last empty strings if they exist due to leading/trailing '|'
        if parts and parts[0] == '':
            parts = parts[1:]
        if parts and parts[-1] == '':
            parts = parts[:-1]

        if not parts:
            continue

        row = []
        for p in parts:
            if p == '':
                continue
            try:
                row.append(int(p))
            except ValueError:
                # Ignore non-integer tokens
                continue
        if row:
            result.append(row)

    return result
```

