from functools import wraps

def outdated(alternative_func):
    def decorator(func):
        call_count = 0

        @wraps(func)
        def wrapper(*args, **kwargs):
            nonlocal call_count
            call_count += 1
            print(f"Warning: '{func.__name__}' is outdated. Consider using '{alternative_func.__name__}' instead. Function '{func.__name__}' has been called {call_count} times.")
            return func(*args, **kwargs)

        return wrapper

    return decorator
