def fibonacci_sequence(n, memo={}):
    if n < 1:
        return []

    def fib(k):
        if k in memo:
            return memo[k]
        if k == 0:
            result = 0
        elif k == 1:
            result = 1
        else:
            result = fib(k - 1) + fib(k - 2)
        memo[k] = result
        return result

    sequence = [fib(i) for i in range(n)]
    return sequence
```

