def generate_prime_sequence():
    """
    An infinite generator that yields prime numbers in ascending order.
    Yields: 2, 3, 5, 7, 11, 13, ...
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    num = 2
    while True:
        if is_prime(num):
            yield num
        num += 1
