def is_parabola(points):
    # Empty list is considered valid
    if not points:
        return True

    # We need to find a positive constant 'a' such that y = a * x^2 for all points.
    # If any point has x == 0, then y must be 0 (since y = a * 0^2 = 0).
    # If we have a point (0, y) with y != 0, it's invalid.
    for x, y in points:
        if x == 0:
            if y != 0:
                return False

    # Determine 'a' from the first non-zero x point
    a = None
    for x, y in points:
        if x != 0:
            a = y / (x * x)
            break

    # If all points are (0, 0), then any positive a works; we can consider it True.
    if a is None:
        return True

    # Check that 'a' is positive
    if a <= 0:
        return False

    # Verify all points satisfy y = a * x^2 with the computed 'a'
    for x, y in points:
        expected_y = a * (x * x)
        # Use a small tolerance for floating-point comparisons
        if abs(y - expected_y) > 1e-9:
            return False

    return True
```

