def get_nth_digit(num, n):
    # Attempt to convert num and n to positive integers
    try:
        num = int(num)
        n = int(n)
    except (TypeError, ValueError):
        return None

    # Check if they are positive integers
    if num <= 0 or n <= 0:
        return None

    # Check if n is greater than the number of digits in num
    num_str = str(num)
    if n > len(num_str):
        return 0

    # Return the nth digit from the right (1-based index)
    return int(num_str[-n])
```

