def inventory_update_needed(current_inventory, desired_inventory):
    # Helper to extract item_id and quantity from a dict without using .keys(), .values(), .items()
    def get_id_qty(d):
        return (d['item_id'], d['quantity'])

    # Helper to check if two lists are equal in content and order without using == or set()
    def lists_equal(list1, list2):
        if len(list1) != len(list2):
            return False
        for i in range(len(list1)):
            if get_id_qty(list1[i]) != get_id_qty(list2[i]):
                return False
        return True

    # We need to check if the multisets of (item_id, quantity) are the same.
    # Since we cannot use set() or dict.items(), we will sort both lists by item_id
    # and then compare element-wise.

    def make_copy(lst):
        new_lst = []
        for item in lst:
            new_lst.append(item)
        return new_lst

    def sort_by_item_id(lst):
        # Simple bubble sort based on item_id
        n = len(lst)
        arr = make_copy(lst)
        for i in range(n):
            for j in range(0, n - i - 1):
                id_j = arr[j]['item_id']
                id_next = arr[j + 1]['item_id']
                if id_j > id_next:
                    arr[j], arr[j + 1] = arr[j + 1], arr[j]
        return arr

    sorted_current = sort_by_item_id(current_inventory)
    sorted_desired = sort_by_item_id(desired_inventory)

    if len(sorted_current) != len(sorted_desired):
        return True

    for i in range(len(sorted_current)):
        c = sorted_current[i]
        d = sorted_desired[i]
        if c['item_id'] != d['item_id']:
            return True
        if c['quantity'] != d['quantity']:
            return True

    return False
