def zip_with_padding(*args):
    # Check that all arguments are iterable and can be converted to tuples
    for arg in args:
        try:
            tuple(arg)
        except TypeError:
            raise TypeError("All arguments must be iterables that can be converted into tuples")

    # Determine the maximum length among all iterables
    max_length = 0
    for arg in args:
        length = len(arg)
        if length > max_length:
            max_length = length

    # Build the result list of tuples with padding
    result = []
    for i in range(max_length):
        current_tuple = []
        for arg in args:
            try:
                item = arg[i]
            except IndexError:
                item = None
            current_tuple.append(item)
        result.append(tuple(current_tuple))

    return result
```

