def get_even_range(start, stop):
    if start <= stop:
        # Ascending order
        first_even = start if start % 2 == 0 else start + 1
        last_even = stop if stop % 2 == 0 else stop - 1
        return list(range(first_even, last_even + 1, 2))
    else:
        # Descending order
        first_even = start if start % 2 == 0 else start - 1
        last_even = stop if stop % 2 == 0 else stop + 1
        return list(range(first_even, last_even - 1, -2))
```

