def search(nums, target):
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return True

        # Handle duplicates: if nums[left] == nums[mid] == nums[right],
        # we can't determine which side is sorted, so shrink from left.
        if nums[left] == nums[mid] == nums[right]:
            left += 1
            right -= 1
            continue

        # Left side is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        # Right side is sorted
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return False
