def unique_sorted(numbers):
    # Step 1: Remove duplicates manually using a list and a seen set-like structure
    seen = []
    unique_list = []

    for num in numbers:
        is_duplicate = False
        for s in seen:
            if s == num:
                is_duplicate = True
                break
        if not is_duplicate:
            seen.append(num)
            unique_list.append(num)

    # Step 2: Sort the unique list manually using insertion sort
    sorted_list = []
    for num in unique_list:
        inserted = False
        i = 0
        while i < len(sorted_list):
            if sorted_list[i] > num:
                sorted_list.insert(i, num)
                inserted = True
                break
            i += 1
        if not inserted:
            sorted_list.append(num)

    return sorted_list
