def quicksort(arr):
    def median_of_three(left, mid, right):
        a, b, c = arr[left], arr[mid], arr[right]
        if a <= b <= c or c <= b <= a:
            return b
        elif b <= a <= c or c <= a <= b:
            return a
        else:
            return c

    def partition(low, high):
        if high - low < 2:
            # Not enough elements to form a triplet; use first as pivot
            pivot = arr[low]
        else:
            mid = (low + high) // 2
            pivot = median_of_three(low, mid, high)

        # Find the index of the pivot value (any occurrence is fine)
        pivot_index = low
        for i in range(low, high + 1):
            if arr[i] == pivot:
                pivot_index = i
                break

        # Move pivot to the end for standard partitioning
        arr[pivot_index], arr[high] = arr[high], arr[pivot_index]
        pivot = arr[high]

        store_index = low
        for i in range(low, high):
            if arr[i] <= pivot:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1

        # Move pivot to its final place
        arr[store_index], arr[high] = arr[high], arr[store_index]
        return store_index

    def quicksort_recursive(low, high):
        if low < high:
            pi = partition(low, high)
            quicksort_recursive(low, pi - 1)
            quicksort_recursive(pi + 1, high)

    if len(arr) <= 1:
        return arr

    quicksort_recursive(0, len(arr) - 1)
    return arr
```

