def replace_special_characters(text):
    import string

    # Define punctuation marks that should never be replaced even if surrounded by alphanumerics
    # This includes all standard punctuation and common symbols that act as sentence delimiters or separators.
    # We'll use a set of characters that are typically considered punctuation.
    punctuation_set = set(string.punctuation)
    # Also include some common symbols that might appear in text but are not alphanumeric or whitespace
    # and act as delimiters (e.g., @, #, $, %, ^, &, *, _, +, =, {, }, [, ], |, \, :, ";, <, >, ?, /)
    # Note: '_' is already in string.punctuation, but we'll ensure it's covered.
    # The problem says "not a punctuation mark from the previous sentence", which is ambiguous.
    # However, the sample output shows that commas, exclamation marks, hyphens, underscores, etc. are NOT replaced.
    # So we interpret "punctuation mark" as any character in string.punctuation.

    def is_alnum(c):
        return c.isalnum()

    def is_special(c):
        return not c.isalnum() and not c.isspace()

    def is_punctuation(c):
        return c in punctuation_set

    result = []
    n = len(text)

    for i in range(n):
        c = text[i]

        if is_special(c):
            # Check if it's a punctuation mark -> do not replace
            if is_punctuation(c):
                result.append(c)
                continue

            # Check if surrounded by two alphanumeric characters
            left_ok = (i > 0) and is_alnum(text[i - 1])
            right_ok = (i < n - 1) and is_alnum(text[i + 1])

            if left_ok and right_ok:
                # Replace with space
                result.append(' ')
            else:
                # Keep as is
                result.append(c)
        else:
            result.append(c)

    return ''.join(result)
