def deep_search(dictionary, keys, default=None):
    seen = set()
    current = dictionary

    for key in keys:
        if current is None:
            return default

        # Check for circular reference by object identity
        if id(current) in seen:
            return default
        seen.add(id(current))

        if not isinstance(current, dict):
            return default

        if key not in current:
            return default

        current = current[key]

    return current if current is not None else default
