def similarity_score_prime_indices(target_str, rand_str):
    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        i = 3
        while i * i <= k:
            if k % i == 0:
                return False
            i += 2
        return True

    n = len(target_str)
    if n != len(rand_str):
        raise ValueError("Strings must be of equal length")

    matches = 0
    total_primes = 0

    for i in range(1, n):  # skip index 0 as per spec
        if is_prime(i):
            total_primes += 1
            if target_str[i] == rand_str[i]:
                matches += 1

    if total_primes == 0:
        return 0.0

    score = matches / total_primes
    return round(score, 6)
