def _escape_html(obj):
    """
    Recursively escape HTML special characters in strings within dictionaries and lists.

    Escapes:
        <  -> &lt;
        >  -> &gt;
        "  -> &quot;
        '  -> &apos;
        &  -> &amp;

    Non-string, non-collection types are returned as-is.
    """
    if isinstance(obj, str):
        return (
            obj
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
            .replace("'", "&apos;")
        )
    elif isinstance(obj, dict):
        return {
            _escape_html(k): _escape_html(v)
            for k, v in obj.items()
        }
    elif isinstance(obj, (list, tuple)):
        return type(obj)(_escape_html(item) for item in obj)
    else:
        return obj
