def is_strong_probable_prime(n: int) -> bool:
    """
    Determine if n is a strong probable prime with respect to the first 12 primes
    congruent to 3 mod 4: [3, 7, 11, 19, 23, 31, 43, 47, 59, 67, 71, 79].

    Returns True if n passes the strong probable prime test for all these bases,
    otherwise False.
    """
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Write n-1 as d * 2^s
    d = n - 1
    s = 0
    while d % 2 == 0:
        d //= 2
        s += 1

    bases = [3, 7, 11, 19, 23, 31, 43, 47, 59, 67, 71, 79]

    for a in bases:
        if a % n == 0:
            continue
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = pow(x, 2, n)
            if x == n - 1:
                break
        else:
            return False

    return True
```

