def checkInclusion(P, S):
    # Frequency arrays for 26 lowercase and 26 uppercase letters
    # We'll map 'a'-'z' to 0-25 and 'A'-'Z' to 26-51
    def get_index(char):
        if 'a' <= char <= 'z':
            return ord(char) - ord('a')
        else:
            return ord(char) - ord('A') + 26

    def build_freq_string(freq):
        # Convert frequency list to a string representation for comparison
        # Since we cannot use sorting or multisets, we use a tuple of frequencies
        return tuple(freq)

    len_p = len(P)
    len_s = len(S)

    if len_p > len_s:
        return False

    # Initialize frequency arrays
    p_freq = [0] * 52
    window_freq = [0] * 52

    for char in P:
        idx = get_index(char)
        p_freq[idx] += 1

    # Initialize first window in S
    for i in range(len_p):
        idx = get_index(S[i])
        window_freq[idx] += 1

    # Check first window
    if p_freq == window_freq:
        return True

    # Slide the window
    for i in range(len_p, len_s):
        # Add new character
        new_char_idx = get_index(S[i])
        window_freq[new_char_idx] += 1

        # Remove old character
        old_char_idx = get_index(S[i - len_p])
        window_freq[old_char_idx] -= 1

        # Compare
        if p_freq == window_freq:
            return True

    return False
```

