def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0:
        return True

    # Use integer square root via binary search to avoid floating-point issues
    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            low = mid + 1
        else:
            high = mid - 1

    return False
