import json
import re
import sys

def to_snake_case(name):
    """Convert camelCase or PascalCase to snake_case."""
    # Insert underscore before uppercase letters that follow lowercase letters or numbers
    s1 = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', name)
    # Insert underscore before uppercase letters that are followed by lowercase letters (to handle consecutive capitals like 'XMLParser' -> 'xml_parser')
    s2 = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s1)
    return s2.lower()

def process_input_data(input_source):
    """
    Process JSON data from either a file path or a JSON string.
    Converts all keys from camelCase/PascalCase to snake_case.
    Returns the transformed JSON as a string.
    """
    data = None

    if input_source.startswith(('http://', 'https://')):
        raise ValueError("URL input is not supported in this implementation.")
    elif input_source.startswith('{') or input_source.startswith('['):
        # Treat as JSON string
        data = json.loads(input_source)
    else:
        # Treat as file path
        with open(input_source, 'r', encoding='utf-8') as f:
            data = json.load(f)

    def convert_keys(obj):
        if isinstance(obj, dict):
            return {to_snake_case(k): convert_keys(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [convert_keys(item) for item in obj]
        else:
            return obj

    transformed_data = convert_keys(data)
    return json.dumps(transformed_data, indent=2)

if __name__ == "__main__":
    if len(sys.argv) > 1:
        result = process_input_data(sys.argv[1])
        print(result)
    else:
        print("Usage: python script.py <json_file_path_or_json_string>")
