def convert_temperature(temperature, initial_unit, final_unit):
    # Validate input types
    if not isinstance(temperature, (int, float)):
        return None
    if not isinstance(initial_unit, str) or not isinstance(final_unit, str):
        return None

    # Normalize unit names
    unit_map = {'Celsius': 'C', 'Fahrenheit': 'F', 'Kelvin': 'K'}
    initial_unit = initial_unit.capitalize()
    final_unit = final_unit.capitalize()

    if initial_unit not in unit_map or final_unit not in unit_map:
        return None

    # Convert to Kelvin first
    try:
        if initial_unit == 'C':
            kelvin = temperature + 273.15
        elif initial_unit == 'F':
            kelvin = (temperature - 32) * 5.0 / 9.0 + 273.15
        elif initial_unit == 'K':
            kelvin = temperature
    except Exception:
        return None

    # Convert from Kelvin to final unit
    try:
        if final_unit == 'C':
            result = kelvin - 273.15
        elif final_unit == 'F':
            result = (kelvin - 273.15) * 9.0 / 5.0 + 32
        elif final_unit == 'K':
            result = kelvin
        else:
            return None
    except Exception:
        return None

    return float(result)
