def count_unique_letters(text):
    # Initialize a list to act as our own set (to track unique letters)
    unique_chars = []

    # Iterate over each character in the string
    for char in text:
        # Check if the character is an alphabetic letter
        is_alpha = False
        if 'a' <= char <= 'z' or 'A' <= char <= 'Z':
            is_alpha = True

        if not is_alpha:
            continue

        # Convert to lowercase for case-insensitive comparison
        lower_char = char
        if 'A' <= char <= 'Z':
            lower_char = chr(ord(char) + 32)

        # Check if this character is already in our unique list
        is_unique = True
        for existing in unique_chars:
            if existing == lower_char:
                is_unique = False
                break

        # If not found, add it to the list
        if is_unique:
            unique_chars.append(lower_char)

    # Return the count of unique alphabetic characters
    return len(unique_chars)
