def process_lists(list1, list2):
    def insertion_sort(arr):
        n = len(arr)
        for i in range(1, n):
            key = arr[i]
            j = i - 1
            while j >= 0 and arr[j] > key:
                arr[j + 1] = arr[j]
                j -= 1
            arr[j + 1] = key
        return arr

    # Find intersection
    intersection = []
    for x in list1:
        if x in list2:
            intersection.append(x)

    # Find elements in list2 but not in list1
    diff = []
    for x in list2:
        if x not in list1:
            diff.append(x)

    # Sort both lists using custom insertion sort
    intersection_sorted = insertion_sort(intersection.copy())
    diff_sorted = insertion_sort(diff.copy())

    return (intersection_sorted, diff_sorted)
