def check_monotonicity(iterator):
    try:
        first = next(iterator)
    except StopIteration:
        return True

    is_increasing = True
    is_decreasing = True

    for value in iterator:
        if value <= first:
            is_increasing = False
        if value >= first:
            is_decreasing = False
        if not is_increasing and not is_decreasing:
            return False
        # Update reference for next comparison
        first = value

