def binarySearchRecursive(low, high, numbers, target):
    # Base case: if the search range is invalid, the target is not found
    if low > high:
        return False

    mid = (low + high) // 2

    # Check if the middle element is the target
    if numbers[mid] == target:
        return True
    elif numbers[mid] < target:
        # Search in the right half
        return binarySearchRecursive(mid + 1, high, numbers, target)
    else:
        # Search in the left half
        return binarySearchRecursive(low, mid - 1, numbers, target)
