def encrypt_message(message, key):
    result = []
    for char in message:
        if 'A' <= char <= 'Z':
            # Uppercase letters
            shifted = chr((ord(char) - ord('A') + key) % 26 + ord('A'))
            result.append(shifted)
        elif 'a' <= char <= 'z':
            # Lowercase letters
            shifted = chr((ord(char) - ord('a') + key) % 26 + ord('a'))
