from typing import List

def paragraph_tokenize(text: str, engine: str) -> List[str]:
    if not isinstance(text, str):
        return []

    if not text:
        return []

    if engine == "double_newline":
        paragraphs = text.split("\n\n")
    elif engine == "tab_indentation":
        # Split on newline, then treat consecutive tabs at the start of a line as paragraph breaks
        lines = text.split("\n")
        paragraphs = []
        current_para_lines = []

        for line in lines:
            # Check if line starts with one or more tabs
            if line.startswith("\t"):
                if current_para_lines:
                    paragraphs.append("\n".join(current_para_lines))
                    current_para_lines = []
            else:
                current_para_lines.append(line)

        if current_para_lines:
            paragraphs.append("\n".join(current_para_lines))
    else:
        return []

    # Trim leading and trailing spaces from each paragraph
    result = [p.strip() for p in paragraphs]

    # Remove empty strings that may result from consecutive delimiters or leading/trailing whitespace
    return [p for p in result if p]
