import json

def parse_json(json_str):
    """
    Parses a JSON string and extracts all string values at any depth.

    Args:
        json_str (str): A valid JSON string representing a nested object.

    Returns:
        List[str]: A list of all string values found in the JSON structure.
    """
    data = json.loads(json_str)

    def extract_strings(obj):
        result = []
        if isinstance(obj, dict):
            for value in obj.values():
                result.extend(extract_strings(value))
        elif isinstance(obj, list):
            for item in obj:
                result.extend(extract_strings(item))
        elif isinstance(obj, str):
            result.append(obj)
        # Ignore numbers, booleans, null, etc.
        return result

    return extract_strings(data)
