    Numbers within 1e-9 of the real or imaginary axis are considered to lie on the axis.

    Returns:
        str: One of:
            "First quadrant", "Second quadrant", "Third quadrant", "Fourth quadrant",
            "X-axis positive", "X-axis negative", "Y-axis positive", "Y-axis negative",
            "Origin"
    """
    x = z.real
    y = z.imag
    eps = 1e-9

    # Check if on axes
    if abs(x) < eps and abs(y) < eps:
        return "Origin"
    if abs(x) < eps:
        if y > eps:
            return "Y-axis positive"
        elif y < -eps:
            return "Y-axis negative"
        else:
            # Should be caught by Origin, but for safety
            return "Origin"
    if abs(y) < eps:
        if x > eps:
            return "X-axis positive"
        elif x < -eps:
            return "X-axis negative"
        else:
            return "Origin"

    # Determine quadrant
    if x > 0 and y > 0:
        return "First quadrant"
    if x < 0 and y > 0:
        return "Second quadrant"
    if x < 0 and y < 0:
        return "Third quadrant"
    if x > 0 and y < 0:
        return "Fourth quadrant"

    # Fallback (should not reach here)
    return "Unknown"
```

