def shortest_distance_on_circle(angle1, angle2):
    # Normalize angles to [0, 360) without using modulo or trig
    def normalize(a):
        # Subtract multiples of 360 until in [0, 360)
        while a < 0:
            a += 360
        while a >= 360:
            a -= 360
        return a

    a1 = normalize(angle1)
    a2 = normalize(angle2)

    diff = abs(a1 - a2)
    # Shortest arc is min(diff, 360 - diff)
    return min(diff, 360 - diff)
