def common_elements(list1, list2):
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    flat1 = flatten(list1)
    flat2 = flatten(list2)

    # Determine shorter and longer lists
    if len(flat1) <= len(flat2):
        shorter, longer = flat1, flat2
    else:
        shorter, longer = flat2, flat1

    # Build result using list comprehension and manual membership check
    result = []
    for elem in shorter:
        found = False
        for candidate in longer:
            if elem == candidate:
                found = True
                break
        if not found:
            continue
        # Add only if not already in result (to ensure uniqueness)
        is_duplicate = False
        for existing in result:
            if elem == existing:
                is_duplicate = True
                break
        if not is_duplicate:
            result.append(elem)

    return result
