import heapq

def find_k_largest(nums, k):
    """
    Returns the k largest elements from nums in ascending order.
    Time complexity: O(n log k), which is better than O(n log n) for k < n.
    """
    if k <= 0:
        return []
    if k >= len(nums):
        return sorted(nums)

    # Use a min-heap of size k to keep track of the k largest elements
    heap = nums[:k]
    heapq.heapify(heap)

    for num in nums[k:]:
        if num > heap[0]:
            heapq.heapreplace(heap, num)

    # The heap contains the k largest elements, but in arbitrary order.
    # Sort them in ascending order before returning.
    return sorted(heap)
```

