def merge_and_sort_dicts(dict1, dict2):
    # Merge dict1 and dict2, preserving order from dict1 then dict2
    merged = {}
    for key in dict1:
        merged[key] = dict1[key]
    for key in dict2:
        if key not in merged:
            merged[key] = dict2[key]

    # Create a list of (value, key) to sort by value descending,
    # and use insertion order as tie-breaker (stable sort)
    items = [(v, k) for k, v in merged.items()]
    # Sort by value descending; Python's sort is stable, so equal values keep original order
    items.sort(key=lambda x: x[0], reverse=True)

    # Reconstruct dictionary from sorted items
    sorted_dict = {k: v for v, k in items}
    return sorted_dict
