from urllib.parse import urlparse, parse_qs, urlencode, urlunparse

def construct_url_with_params(base_url, params_dict):
    # Parse the base URL
    parsed = urlparse(base_url)

    # Parse existing query parameters
    existing_params = parse_qs(parsed.query, keep_blank_values=True)

    # Merge parameters: dictionary params take precedence
    merged_params = {}

    # Add existing parameters (flattened from list of values to single value if only one)
    for key, values in existing_params.items():
        if len(values) == 1:
            merged_params[key] = values[0]
        else:
            # If multiple values exist, we'll handle them appropriately
            # For simplicity, we'll take the first value if duplicates exist
            merged_params[key] = values[0]

    # Update with new parameters from params_dict
    for key, value in params_dict.items():
        merged_params[key] = value

    # Rebuild the query string
    # Ensure we handle both string and non-string values by converting to string
    final_params = {}
    for key, value in merged_params.items():
        final_params[key] = str(value)

    query_string = urlencode(final_params, doseq=False)

    # Reconstruct the URL
    if query_string:
        new_query = query_string
    else:
        new_query = ""

    new_parsed = parsed._replace(query=new_query)
    return urlunparse(new_parsed)
