def find_max_prime_divisor(n: int):
    if n < 2:
        return None

    max_prime = None

    # Remove factors of 2
    if n % 2 == 0:
        max_prime = 2
        while n % 2 == 0:
            n //= 2

    # Check odd factors up to sqrt(n)
    i = 3
    limit = int(n**0.5) + 1
    while i <= limit and n > 1:
        if n % i == 0:
            max_prime = i
            while n % i == 0:
                n //= i
            # Update limit since n has decreased
            limit = int(n**0.5) + 1
        i += 2

    # If n > 1 after the loop, the remaining n is a prime
    if n > 1:
        max_prime = n

    return max_prime
