class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generate_binary_tree(preorder, inorder):
    if not preorder or not inorder:
        return None

    # Map value to its index in inorder for O(1) lookup
    inorder_index_map = {val: i for i, val in enumerate(inorder)}

    def build(pre_start, pre_end, in_start, in_end):
        if pre_start >= pre_end or in_start >= in_end:
            return None

        root_val = preorder[pre_start]
        root = TreeNode(root_val)

        root_index_in_inorder = inorder_index_map[root_val]
        left_subtree_size = root_index_in_inorder - in_start

        root.left = build(
            pre_start + 1,
            pre_start + 1 + left_subtree_size,
            in_start,
            root_index_in_inorder
        )

        root.right = build(
            pre_start + 1 + left_subtree_size,
            pre_end,
            root_index_in_inorder + 1,
            in_end
        )

        return root

    return build(0, len(preorder), 0, len(inorder))
```

