import math
import statistics

def gaussian_uncertainty(x, default=1):
    # Filter out NaN values
    valid_values = [val for val in x if not math.isnan(val)]

    # Check edge cases: empty, all zeros, or no valid values after filtering
    if not valid_values:
        return default

    # Check if all valid values are zero
    if all(val == 0 for val in valid_values):
        return default

    # Compute standard deviation
    try:
        return statistics.stdev(valid_values)
    except statistics.StatisticsError:
        # Fallback if less than two values (stdev requires at least 2)
        return default
