    s1 = s1.replace(" ", "").lower()
    s2 = s2.replace(" ", "").lower()

    # If lengths differ, they cannot be anagrams
    if len(s1) != len(s2):
        return False

    # Count character frequencies
    count = {}
    for char in s1:
        count[char] = count.get(char, 0) + 1

    for char in s2:
        if char not in count:
            return False
        count[char] -= 1
        if count[char] < 0:
            return False

    # All counts should be zero
    return all(v == 0 for v in count.values())
