```python
def dfs_traversal(edges):
    # Build adjacency representation: node -> (left, right)
    children = {}
    for root, left, right in edges:
        children[root] = (left, right)

    # Find root: the node that never appears as a child
    all_nodes = set()
    all_children = set()
    for root, left, right in edges:
        all_nodes.add(root)
        if left is not None:
            all_children.add(left)
        if right is not None:
            all_children.add(right)

    root = None
    for node in all_nodes:
        if node not in all_children:
            root = node
            break

    if root is None:
        return []

    result = []

    def dfs(node):
        if node is None:
            return
        result.append(node)
        left, right = children.get(node, (None, None))
        dfs(left)
        dfs(right)

    dfs(root)
    return result
```

