import random

def find_kth_smallest(arr, k):
    """
    Find the k-th smallest element in an unsorted list using Quickselect.
    k is 1-based.
    """
    if not arr or k < 1 or k > len(arr):
        raise ValueError("Invalid k or empty array")

    def quickselect(left, right, target_k):
        if left == right:
            return arr[left]

        # Random pivot to avoid worst-case on sorted inputs
        pivot_index = random.randint(left, right)
        pivot_value = arr[pivot_index]

        # Move pivot to the end
        arr[pivot_index], arr[right] = arr[right], arr[pivot_index]

        store_index = left
        for i in range(left, right):
            if arr[i] < pivot_value:
                arr[store_index], arr[i] = arr[i], arr[store_index]
                store_index += 1

        # Move pivot to its final place
        arr[store_index], arr[right] = arr[right], arr[store_index]
        pivot_final_index = store_index

        if target_k == pivot_final_index + 1:
            return arr[pivot_final_index]
        elif target_k < pivot_final_index + 1:
            return quickselect(left, pivot_final_index - 1, target_k)
        else:
            return quickselect(pivot_final_index + 1, right, target_k)

    # Convert 1-based k to 0-based index
    return quickselect(0, len(arr) - 1, k)
```

