def cube_root(N, tolerance=1e-06, max_iterations=100):
    if N < 0:
        raise ValueError("N must be non-negative.")
    if N == 0:
        return 0.0

    x = N  # Initial guess
    for _ in range(max_iterations):
        x_next = (2 * x + N / (x * x)) / 3  # Newton-Raphson for cube root
        if abs(x_next - x) < tolerance:
            break
        x = x_next

    return round(x, 3)
