def prettyPrint(v):
    # Handle zero explicitly
    if v == 0:
        return "0"

    abs_v = abs(v)

    # Check if it's effectively an integer (within floating point tolerance)
    if v == int(v):
        i = int(v)
        if -1000 < i < 1000:
            return str(i)
        # For integers with abs >= 1000, return as integer string
        return str(i)

    # Determine magnitude-based formatting
    if abs_v >= 1000 or abs_v <= 0.001:
        return f"{v:.1e}"
    elif abs_v < 0.01:
        return f"{v:.4f}"
    elif abs_v < 0.1:
        return f"{v:.3f}"
    elif abs_v < 1:
        return f"{v:.2f}"
    elif abs_v < 10:
        return f"{v:.1f}"
    elif abs_v < 100:
        return f"{v:.1f}"
    else:
        # abs_v >= 100 and not an integer -> format as integer? 
        # But spec says "Otherwise, return v as an integer."
        # Since we already handled the integer case above, this branch means
        # v is not an integer but abs(v) >= 100. We'll round to nearest integer.
        return str(round(v))
