def is_unique_sorted_and_reversed(s):
    # Convert string to list of characters and sort it (O(n log n))
    chars = sorted(s)

    # Check uniqueness in the sorted original string
    for i in range(1, len(chars)):
        if chars[i] == chars[i - 1]:
            return False

    # Reverse the sorted list (O(n))
    reversed_chars = chars[::-1]

    # Check uniqueness in the reversed sorted string
    for i in range(1, len(reversed_chars)):
        if reversed_chars[i] == reversed_chars[i - 1]:
            return False

    return True
