def infix_to_postfix(expression):
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        '^': 3
    }

    right_associative = {'^'}

    def output():
        while output_stack and (
            not right_associative.get(output_stack[-1], False) or
            precedence.get(output_stack[-1], 0) >= precedence.get(token, 0)
        ):
            yield output_stack.pop()

    output_stack = []
    output_list = []

    tokens = expression.split()

    for token in tokens:
        if token.isdigit() or (token.startswith('-') and len(token) > 1 and token[1:].isdigit()):
            output_list.append(token)
        elif token in precedence:
            while (
                output_stack and
                output_stack[-1] in precedence and
                (
                    not right_associative.get(output_stack[-1], False) or
                    precedence.get(output_stack[-1], 0) >= precedence.get(token, 0)
                )
            ):
                output_list.append(output_stack.pop())
            output_stack.append(token)
        elif token == '(':
            output_stack.append(token)
        elif token == ')':
            while output_stack and output_stack[-1] != '(':
                output_list.append(output_stack.pop())
            if output_stack and output_stack[-1] == '(':
                output_stack.pop()
            else:
                raise ValueError("Mismatched parentheses")
        else:
            raise ValueError(f"Invalid token: {token}")

    while output_stack:
        output_list.append(output_stack.pop())

    return ' '.join(output_list)
