def find_largest_rectangle(matrix):
    if not matrix or not matrix[0]:
        return 0

    m, n = len(matrix), len(matrix[0])
    height = [0] * n
    max_area = 0

    for i in range(m):
        for j in range(n):
            if matrix[i][j] == 1:
                height[j] += 1
            else:
                height[j] = 0

        # Compute largest rectangle in histogram for current row
        stack = []  # stores indices
        for j in range(n + 1):
            h = height[j] if j < n else 0
            while stack and height[stack[-1]] > h:
                h_idx = stack.pop()
                width = j if not stack else j - stack[-1] - 1
                area = height[h_idx] * width
                if area > max_area:
                    max_area = area
            stack.append(j)

    return max_area
```

