def is_acyclic(graph):
    """
    Determines whether a directed graph is acyclic using DFS with three states:
    0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited.

    :param graph: dict mapping node -> list of successor nodes
    :return: True if the graph is acyclic, False otherwise
    """
    n = len(graph)
    # Ensure all nodes from 0 to n-1 are present in the graph dict
    for i in range(n):
        if i not in graph:
            graph[i] = []

    state = [0] * n  # 0: unvisited, 1: visiting, 2: visited

    def dfs(node):
        if state[node] == 1:
            # Back edge found -> cycle
            return True
        if state[node] == 2:
            # Already fully processed
            return False

        state[node] = 1  # Mark as visiting

        for neighbor in graph.get(node, []):
            if neighbor < 0 or neighbor >= n:
                # Ignore invalid neighbors if any
                continue
            if dfs(neighbor):
                return True

        state[node] = 2  # Mark as visited
        return False

    for i in range(n):
        if state[i] == 0:
            if dfs(i):
                return False

    return True
```

