def normalize_dataset(dataset):
    if not dataset:
        return []

    num_rows = len(dataset)
    num_cols = len(dataset[0])
    normalized = [[None for _ in range(num_cols)] for _ in range(num_rows)]

    for col_idx in range(num_cols):
        values = [row[col_idx] for row in dataset if row[col_idx] is not None]

        if not values:
            # No valid values in this column; keep all as None
            continue

        min_val = min(values)
        max_val = max(values)

        if min_val == max_val:
            # All values are the same; normalized value is 0.0
            for row_idx in range(num_rows):
                if dataset[row_idx][col_idx] is not None:
                    normalized[row_idx][col_idx] = 0.0
        else:
            for row_idx in range(num_rows):
                if dataset[row_idx][col_idx] is not None:
                    normalized[row_idx][col_idx] = (dataset[row_idx][col_idx] - min_val) / (max_val - min_val)

    return normalized
