def recursive_power(base: int, exponent: int, memo=None) -> int:
    if memo is None:
        memo = {}

    if exponent == 0:
        return 1
    if exponent == 1:
        return base

    key = (base, exponent)
    if key in memo:
        return memo[key]

    # Use exponentiation by squaring for efficiency
    if exponent % 2 == 0:
        half = recursive_power(base, exponent // 2, memo)
        result = half * half
    else:
        half = recursive_power(base, exponent // 2, memo)
        result = half * half * base

    memo[key] = result
    return result
```

