def find_infected_computers(networks):
    """
    networks: list of tuples (I, P, packets)
      I: int, initially infected computer ID
      P: int, number of packets
      packets: list of tuples (S, D), packet from S to D

    Returns:
      list of lists, each inner list contains infected computer IDs in ascending order
    """
    results = []

    for I, P, packets in networks:
        infected = {I}
        # Build adjacency list for the current network
        adj = {}
        for S, D in packets:
            if S not in adj:
                adj[S] = []
            adj[S].append(D)

        # BFS to propagate infection
        queue = [I]
        visited = {I}
        while queue:
            current = queue.pop(0)
            if current in adj:
                for neighbor in adj[current]:
                    if neighbor not in visited:
                        visited.add(neighbor)
                        queue.append(neighbor)

        results.append(sorted(visited))

    return results
