def path_parser(paths):
    result = []
    for path in paths:
        current = path
        while True:
            if current == "" or current == "/":
                break
            if current.startswith("/"):
                current = current[1:]
            # Find the last occurrence of '/' without using split
            last_slash = -1
            i = len(current) - 1
            while i >= 0:
                if current[i] == '/':
                    last_slash = i
                    break
                i -= 1

            if last_slash == -1:
                # No more slashes, take the rest as the last component
                result.append(current)
                break

            # Extract component after the last slash
            component = current[last_slash + 1:]
            if component:
                result.append(component)
            # Move to the part before the last slash
            current = current[:last_slash]

    return result
```

