def filter_primes(lst):
    if not lst:
        return []

    max_val = max(lst)
    if max_val < 2:
        return []

    # Sieve of Eratosthenes
    is_prime = [True] * (max_val + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p <= max_val:
        if is_prime[p]:
            for multiple in range(p * p, max_val + 1, p):
                is_prime[multiple] = False
        p += 1

    # Filter original list using the sieve
    return [num for num in lst if is_prime[num]]
