        return result

    for row_idx, row in enumerate(array2d):
        if not isinstance(row, list):
            continue  # Skip non-list rows if any
        for col_idx, item in enumerate(row):
            if item is target or (isinstance(item, float) and isinstance(target, float) and item == target):
