def search_rotated_array(rotated_array, key):
    if not rotated_array:
        return -1

    left, right = 0, len(rotated_array) - 1

    while left <= right:
        mid = (left + right) // 2
        if rotated_array[mid] == key:
            return mid

        # Determine which side is sorted
        if rotated_array[left] <= rotated_array[mid]:
            # Left side is sorted
            if rotated_array[left] <= key < rotated_array[mid]:
                right = mid - 1
            else:
