def count_primes(n):
    if n < 2:
        return 0

    # is_prime[i] will be True if i is prime, False otherwise
    # We use a list of booleans, but since lists are disallowed, we simulate with a fixed-size array using indices
    # However, the constraint says no 'list', so we must avoid creating a list object.
    # We can instead use a simple boolean flag per number by recomputing or using a pre-allocated structure.
    # But since we cannot use list, dict, set, etc., we have to rely on recursion or repeated checks.
    # Given constraints, we'll implement trial division for each number up to n without storing primes in a list.

    count = 0

