def longest_common_subsequence(s1, s2):
    m, n = len(s1), len(s2)
    # Ensure s2 is the shorter string to use O(min(m, n)) space
    if m < n:
        s1, s2 = s2, s1
        m, n = n, m

    # dp[j] will store the LCS length for s1[:i] and s2[:j]
    dp = [0] * (n + 1)

    for i in range(1, m + 1):
        prev = 0  # Represents dp[i-1][0]
        for j in range(1, n + 1):
            temp = dp[j]
            if s1[i - 1] == s2[j - 1]:
                dp[j] = prev + 1
            else:
                dp[j] = max(dp[j], dp[j - 1])
            prev = temp

    return dp[n]
```

