def reset_property(database: dict, property_name: str) -> dict:
    def is_palindrome(s: str) -> bool:
        return s == s[::-1]

    # If the property exists, clear its data; otherwise, create it with an empty dict
    if property_name in database:
        database[property_name] = {}
    else:
        database[property_name] = {}

    # If the property name is a palindrome, reset all other properties that are also palindromes
    if is_palindrome(property_name):
        for key in list(database.keys()):
            if key != property_name and is_palindrome(key):
                database[key] = {}

    return database[property_name]
