def generate_unique_name(base_name, used_names):
    # Convert used_names to a set for O(1) lookup by manually checking membership
    used_set = []
    for name in used_names:
        used_set.append(name)

    # Check if base_name is already used
    is_used = False
    for name in used_set:
        if name == base_name:
            is_used = True
            break

    if not is_used:
        return base_name

    # Find the smallest positive integer n such that base_name + str(n) is not in used_names
    n = 1
    while True:
        # Build candidate name manually without using join or split
        candidate = base_name
        digit = n
        while digit > 0:
            remainder = digit % 10
            digit = digit // 10
            # Convert remainder to character manually
            if remainder == 0:
                candidate = candidate + '0'
            elif remainder == 1:
                candidate = candidate + '1'
            elif remainder == 2:
                candidate = candidate + '2'
            elif remainder == 3:
                candidate = candidate + '3'
            elif remainder == 4:
                candidate = candidate + '4'
            elif remainder == 5:
                candidate = candidate + '5'
            elif remainder == 6:
                candidate = candidate + '6'
            elif remainder == 7:
                candidate = candidate + '7'
            elif remainder == 8:
                candidate = candidate + '8'
            elif remainder == 9:
                candidate = candidate + '9'

        # Check if candidate is in used_names
        is_in_use = False
        for name in used_set:
            if name == candidate:
                is_in_use = True
                break

        if not is_in_use:
            return candidate

        n = n + 1
