def clean_text(input_string: str) -> str:
    result = []
    prev_space = False

    for char in input_string:
        if char.isalpha():
            result.append(char.lower())
            prev_space = False
        elif char.isalnum():
            result.append(char)
            prev_space = False
        else:
            if not prev_space:
                result.append(' ')
                prev_space = True

    # Join and collapse multiple spaces (already handled during construction, but ensure safety)
    cleaned = ''.join(result).strip()

    # Final pass to collapse any remaining multiple spaces just in case
    parts = cleaned.split()
    return ' '.join(parts)
