import pdb
import sys

def debug_on_error(func):
    def wrapper(*args, **kwargs):
        try:
            return func(*args, **kwargs)
        except Exception:
            # Find the innermost exception frame
            exc_type, exc_value, exc_tb = sys.exc_info()
            # Walk up the traceback to find the deepest frame that is not in this wrapper
            while exc_tb.tb_next is not None:
                exc_tb = exc_tb.tb_next
                # Stop if we hit a frame inside this wrapper (to avoid re-debugging our own stack)
                if exc_tb.tb_frame.f_code.co_name == wrapper.__name__:
                    break

            # Start pdb at the innermost exception frame
            pdb.post_mortem(exc_tb)
            # Re-raise the exception so it can be handled by outer catchers
            raise

    return wrapper
```

