def parse_key_value_pairs(strings):
    result = []
    for s in strings:
        pairs = s.split()
        kv_dict = {}
        for pair in pairs:
            if '=' not in pair:
                continue
            key, value = pair.split('=', 1)
            # Ensure key is exactly 3 alphabetic characters (optional validation)
            if len(key) == 3 and key.isalpha():
                kv_dict[key] = value
        # Sort keys alphabetically
        sorted_dict = {k: kv_dict[k] for k in sorted(kv_dict.keys())}
        result.append(sorted_dict)
    return result
