import functools

def log_function_call(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Build the argument string
        parts = []
        if args:
            for i, arg in enumerate(args):
                parts.append(f"{arg}")
        if kwargs:
            for key, value in kwargs.items():
                parts.append(f"{key}={value}")

        # If there are positional args, we need to format them as positional in the log
        # But the sample shows keyword style for all. Let's follow the sample strictly:
        # The sample: multiply(6, 7) -> "Calling multiply(x=6, y=7)"
        # So we must use the function's parameter names.

        import inspect
        sig = inspect.signature(func)
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()

        arg_strs = []
        for name, value in bound.arguments.items():
            arg_strs.append(f"{name}={value}")

        print(f"Calling {func.__name__}({', '.join(arg_strs)})")

        return func(*args, **kwargs)

    return wrapper
