def find_best_gene_names(memberlist, accession_to_gene, prot_id_to_accession):
    result = {}

    for prot_id in memberlist:
        accessions = prot_id_to_accession.get(prot_id)
        if not accessions:
            result[prot_id] = ""
            continue

        gene_counts = {}

        for acc in accessions:
            if acc not in accession_to_gene:
                continue
            for gene in accession_to_gene[acc]:
                gene_counts[gene] = gene_counts.get(gene, 0) + 1

        if not gene_counts:
            result[prot_id] = ""
            continue

        max_count = max(gene_counts.values())
        candidates = [gene for gene, count in gene_counts.items() if count == max_count]
        best_gene = min(candidates)

        result[prot_id] = best_gene

    return result
