        self.campus = campus
        self.department = department
        self.code = code

    def __repr__(self):
        return f"Course({self.campus!r}, {self.department!r}, {self.code})"


def sort_courses(courses):
    # Simple selection sort implementation
    n = len(courses)
    for i in range(n):
        # Assume the current position i has the smallest element
        min_idx = i
        for j in range(i + 1, n):
            c1 = courses[i]
            c2 = courses[j]

            # Compare by campus
            if c1.campus > c2.campus:
                min_idx = j
            elif c1.campus == c2.campus:
                # Compare by department
                if c1.department > c2.department:
                    min_idx = j
                elif c1.department == c2.department:
                    # Compare by code numerically
                    if c1.code > c2.code:
                        min_idx = j

        # Swap the found minimum element with the first element of the unsorted part
        if min_idx != i:
            courses[i], courses[min_idx] = courses[min_idx], courses[i]

    return courses
