def filter_problems_by_difficulty(data, difficulty_levels):
    result = []
    i = 0
    n = len(data)
    while i < n:
        # Find the start of a line (after newline or at beginning)
        if i == 0:
            start = 0
        else:
            start = data.find('\n', i) + 1
            if start <= i:
                start = i

        # Find the end of the line
        end = data.find('\n', start)
        if end == -1:
            end = n

        line = data[start:end]

        # Check if line starts with one of the desired difficulty levels
        matched = False
        for level in difficulty_levels:
            level_len = len(level)
            if line.startswith(level + ": "):
                # Extract description after ": "
                desc_start = level_len + 2  # len(": ") is 2
                if desc_start < len(line):
                    description = line[desc_start:]
                    result.append(description)
                    matched = True
                    break

        i = end

    return result
