import threading

class Group:
    def __init__(self, name, attrs=None):
        self.name = name
        self.attrs = attrs if attrs is not None else {}
        self.subgroups = {}
        self._lock = threading.Lock()

    def to_dict(self):
        return {
            'attrs': self.attrs,
            'subgroups': self.subgroups
        }

class DataManager:
    def __init__(self):
        self._groups = {}
        self._lock = threading.Lock()

    def _get_or_create_group(self, group_name, attrs=None):
        with self._lock:
            if group_name in self._groups:
                return self._groups[group_name]

            new_group = Group(group_name, attrs)
            self._groups[group_name] = new_group
            return new_group

def create_or_get_group(data_manager, group_name, attrs=None):
    group = data_manager._get_or_create_group(group_name, attrs)
    return group.to_dict()
