def modified_quick_sort(arr):
    def median_of_three(a, b, c):
        return sorted([a, b, c])[1]

    def quick_sort_helper(sub_arr):
        if len(sub_arr) <= 1:
            return sub_arr

        # Determine pivot based on length of current subarray
        length = len(sub_arr)
        if length % 2 == 0:
            # Even length: median of first three elements
            pivot = median_of_three(sub_arr[0], sub_arr[1], sub_arr[2])
        else:
            # Odd length: median of first, middle, and last
            mid = length // 2
            pivot = median_of_three(sub_arr[0], sub_arr[mid], sub_arr[-1])

        # Partition
        left = [x for x in sub_arr if x < pivot]
        middle = [x for x in sub_arr if x == pivot]
        right = [x for x in sub_arr if x > pivot]

        return quick_sort_helper(left) + middle + quick_sort_helper(right)

    return quick_sort_helper(arr)
```

