def factorial(n):
    memo = {}

    def _fact(k):
        if k in memo:
            return memo[k]
        if k == 0 or k == 1:
            result = 1
        else:
            result = k * _fact(k - 1)
        memo[k] = result
        return result

    return _fact(n)
