class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def generate_tree(preorder, inorder):
    if len(preorder) != len(inorder):
        raise ValueError("preorder and inorder lists must have the same length")
    if not preorder:
        return None

    # Map value to index in inorder for O(1) lookup
    # In case of duplicates, we use the first occurrence as a heuristic;
    # if the traversals are invalid due to duplicates, this may raise ValueError later.
    inorder_map = {val: i for i, val in enumerate(inorder)}

    def build(pre_start, pre_end, in_start, in_end):
        if pre_start >= pre_end or in_start >= in_end:
            return None

        root_val = preorder[pre_start]
        if root_val not in inorder_map:
            raise ValueError(f"Root value {root_val} not found in inorder traversal")

        root_idx = inorder_map[root_val]

        # Check bounds
        if root_idx < in_start or root_idx >= in_end:
            raise ValueError("Invalid inorder index for root value")

        left_size = root_idx - in_start

        left_child = build(pre_start + 1, pre_start + 1 + left_size, in_start, root_idx)
        right_child = build(pre_start + 1 + left_size, pre_end, root_idx + 1, in_end)

        return TreeNode(root_val, left_child, right_child)

    return build(0, len(preorder), 0, len(inorder))
```

