def validate_date(day, month, year, calendar_type='gregorian'):
    if not (1900 <= year <= 2100):
        return False
    if not (1 <= month <= 12):
        return False
    if not (1 <= day <= 31):
        return False

    # Days in each month for common year
    days_in_month_common = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]

    # Determine leap year based on calendar type
    if calendar_type == 'gregorian':
        is_leap = (year % 4 == 0 and year % 100 != 0) or (year % 400 == 0)
    elif calendar_type == 'julian':
        is_leap = (year % 4 == 0)
    else:
        return False  # Invalid calendar type

    if month == 2:
        max_day = 29 if is_leap else 28
    else:
        max_day = days_in_month_common[month - 1]

    return day <= max_day
