def generate_header(columns, column_labels=None):
    def flatten(lst):
        result = []
        for item in lst:
            if isinstance(item, list):
                result.extend(flatten(item))
            else:
                result.append(item)
        return result

    if column_labels is None:
        column_labels = columns

    flat_columns = flatten(columns)
    flat_labels = flatten(column_labels)

    if len(flat_columns) != len(flat_labels):
        raise ValueError("Flattened columns and column_labels must have the same length.")

    seen = {}
    header = []

    for col, label in zip(flat_columns, flat_labels):
        if label not in seen:
            seen[label] = 1
            header.append(label)
        else:
            count = seen[label]
            while True:
                new_label = f"{label}_{count}"
                if new_label not in seen:
                    seen[new_label] = count + 1
                    header.append(new_label)
                    break
                count += 1

    return ",".join(header)
```

