```python
def validate_bst(tree):
    def is_valid(node, min_val, max_val):
        if node is None:
            return True

        value = node["value"]

        if value <= min_val or value >= max_val:
            return False

        left = node.get("left")
        right = node.get("right")

        # Left subtree must be less than current value
        if not is_valid(left, min_val, value):
            return False

        # Right subtree must be greater than current value
        if not is_valid(right, value, max_val):
            return False

        return True

    return is_valid(tree, float('-inf'), float('inf'))
```

