def rec_palindrome(s):
    def helper(start, end):
        if start >= end:
            return True
        if s[start].lower() != s[end].lower():
            return False
        if s[start].isalnum() and s[end].isalnum():
            return helper(start + 1, end - 1)
        return helper(start + 1, end)

    return helper(0, len(s) - 1)
