def find_sender(tags, prefix):
    # Dictionary to store nicknames and their associated suffixes
    nickname_suffixes = {}

    # Process each tag in the list
    for tag in tags:
        if '=' not in tag:
            continue  # Skip malformed tags

        nick_part, suffix = tag.split('=', 1)
        # Extract nickname from nick_part (format: nick_NICKNAME)
        if not nick_part.startswith('nick_'):
            continue

        nickname = nick_part[5:]  # Remove 'nick_' prefix

        # Check for consistency: same nickname must have same suffix
        if nickname not in nickname_suffixes:
            nickname_suffixes[nickname] = suffix
        elif nickname_suffixes[nickname] != suffix:
            # Inconsistent suffixes found
            return ""

    # If we found consistent nicknames, return the first one
    if nickname_suffixes:
        return nickname_suffixes[next(iter(nickname_suffixes))]

    # Fallback to prefix
    if prefix:
        # Strip leading spaces
        prefix = prefix.lstrip()
        # Remove optional mode characters at the start: @, +, etc.
        # We'll remove any leading non-alphanumeric characters that are common modes
        i = 0
        while i < len(prefix) and prefix[i] in '@+&~':
            i += 1
        nickname = prefix[i:]
        if nickname:
            return nickname

    return ""
