def is_perfect_square(N):
    if N < 1:
        return "NO", None

    # Binary search for the integer square root
    low, high = 1, N
    root = None

    while low <= high:
        mid = (low + high) // 2

        # Compute mid * mid without using * operator
        # Using addition in a loop
        product = 0
        temp = mid
        while temp > 0:
            product += mid
            temp -= 1

        if product == N:
            root = mid
            break
        elif product < N:
            low = mid + 1
        else:
            high = mid - 1

    if root is not None:
        return "YES", root
    else:
        return "NO", None
```

