def find_mode(input_list):
    if not input_list:
        return None

    # Dictionary to store frequency of each string
    freq = {}
    # Track the first occurrence index of each string to resolve ties
    first_occurrence = {}

    max_count = 0
    mode = None

    for i, s in enumerate(input_list):
        if s not in freq:
            freq[s] = 0
            first_occurrence[s] = i
        freq[s] += 1

        # Update mode if current count is strictly greater than max_count
        # This ensures that in case of tie, the one that reached max_count first (and thus appeared earlier) is kept
        if freq[s] > max_count:
            max_count = freq[s]
            mode = s

    return mode
```

